class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> res;
        string path;
        dfs(n, 0, 0, path, res);
        return res;
    }

private:
    void dfs(int n, int open, int close, string& path, vector<string>& res) {
        if ((int)path.size() == 2 * n) {
            res.push_back(path);
            return;
        }
        if (open < n) {                                 // 还能放左括号
            path.push_back('(');
            dfs(n, open + 1, close, path, res);
            path.pop_back();
        }
        if (close < open) {                             // 右括号不能比左括号多
            path.push_back(')');
            dfs(n, open, close + 1, path, res);
            path.pop_back();
        }
    }
};

