func generateParenthesis(n int) []string {
	res, path := []string{}, []byte{}
	var dfs func(open, close int)
	dfs = func(open, close int) {
		if len(path) == 2*n {
			res = append(res, string(path))
			return
		}
		if open < n { // 还能放左括号
			path = append(path, '(')
			dfs(open+1, close)
			path = path[:len(path)-1]
		}
		if close < open { // 右括号不能比左括号多
			path = append(path, ')')
			dfs(open, close+1)
			path = path[:len(path)-1]
		}
	}
	dfs(0, 0)
	return res
}

